  1→/**
  2→ * Load Test Metrics Collection
  3→ *
  4→ * Collects per-operation latency, throughput, and error counts.
  5→ * Uses performance.now() for high-resolution timing.
  6→ */
  7→
  8→export interface OperationMetrics {
  9→  operation: string;
 10→  count: number;
 11→  errors: number;
 12→  latency: { p50: number; p95: number; p99: number; max: number; min: number; avg: number };
 13→  throughputOpsPerSec: number;
 14→  bytesTransferred?: number;
 15→}
 16→
 17→export interface OperationSample {
 18→  operation: string;
 19→  durationMs: number;
 20→  success: boolean;
 21→  bytes?: number;
 22→  timestamp: number;
 23→}
 24→
 25→export class MetricsCollector {
 26→  private samples: OperationSample[] = [];
 27→  private startTime = 0;
 28→  private endTime = 0;
 29→
 30→  start(): void {
 31→    this.startTime = performance.now();
 32→  }
 33→
 34→  stop(): void {
 35→    this.endTime = performance.now();
 36→  }
 37→
 38→  /** Override elapsed time for aggregated collectors (set from sample timestamps). */
 39→  setElapsedMs(ms: number): void {
 40→    this.startTime = 0;
 41→    this.endTime = ms;
 42→  }
 43→
 44→  record(sample: OperationSample): void {
 45→    this.samples.push(sample);
 46→  }
 47→
 48→  /**
 49→   * Wrap an async operation to automatically record metrics.
 50→   */
 51→  async measure<T>(operation: string, fn: () => Promise<T>, bytes?: number): Promise<T> {
 52→    const start = performance.now();
 53→    try {
 54→      const result = await fn();
 55→      this.record({
 56→        operation,
 57→        durationMs: performance.now() - start,
 58→        success: true,
 59→        bytes,
 60→        timestamp: Date.now(),
 61→      });
 62→      return result;
 63→    } catch (err) {
 64→      this.record({
 65→        operation,
 66→        durationMs: performance.now() - start,
 67→        success: false,
 68→        bytes,
 69→        timestamp: Date.now(),
 70→      });
 71→      throw err;
 72→    }
 73→  }
 74→
 75→  /**
 76→   * Get aggregated metrics per operation type.
 77→   */
 78→  getMetrics(): OperationMetrics[] {
 79→    const elapsed = (this.endTime || performance.now()) - this.startTime;
 80→    const elapsedSec = elapsed / 1000;
 81→
 82→    const grouped = new Map<string, OperationSample[]>();
 83→    for (const s of this.samples) {
 84→      const list = grouped.get(s.operation) ?? [];
 85→      list.push(s);
 86→      grouped.set(s.operation, list);
 87→    }
 88→
 89→    const metrics: OperationMetrics[] = [];
 90→    for (const [op, samples] of grouped) {
 91→      const durations = samples.map((s) => s.durationMs).sort((a, b) => a - b);
 92→      const errors = samples.filter((s) => !s.success).length;
 93→      const totalBytes = samples.reduce((sum, s) => sum + (s.bytes ?? 0), 0);
 94→
 95→      metrics.push({
 96→        operation: op,
 97→        count: samples.length,
 98→        errors,
 99→        latency: {
100→          min: durations[0] ?? 0,
101→          avg: durations.reduce((a, b) => a + b, 0) / durations.length,
102→          p50: percentile(durations, 0.5),
103→          p95: percentile(durations, 0.95),
104→          p99: percentile(durations, 0.99),
105→          max: durations[durations.length - 1] ?? 0,
106→        },
107→        throughputOpsPerSec: elapsedSec > 0 ? samples.length / elapsedSec : 0,
108→        ...(totalBytes > 0 ? { bytesTransferred: totalBytes } : {}),
109→      });
110→    }
111→
112→    return metrics.sort((a, b) => a.operation.localeCompare(b.operation));
113→  }
114→
115→  /** Total samples collected */
116→  get totalSamples(): number {
117→    return this.samples.length;
118→  }
119→
120→  /** Total errors across all operations */
121→  get totalErrors(): number {
122→    return this.samples.filter((s) => !s.success).length;
123→  }
124→
125→  /** Raw samples (defensive copy, for JSON export) */
126→  getRawSamples(): OperationSample[] {
127→    return [...this.samples];
128→  }
129→
130→  /** Read-only access to samples (no copy, for aggregation loops) */
131→  getReadonlySamples(): readonly OperationSample[] {
132→    return this.samples;
133→  }
134→}
135→
136→function percentile(sorted: number[], p: number): number {
137→  if (sorted.length === 0) return 0;
138→  const idx = Math.ceil(p * sorted.length) - 1;
139→  return sorted[Math.max(0, idx)];
140→}
141→

  1→/**
  2→ * Load Test Reporter
  3→ *
  4→ * Formats metrics into console table output and JSON export.
  5→ */
  6→
  7→import type { OperationMetrics } from './metrics';
  8→
  9→/**
 10→ * Print a formatted summary table to console.
 11→ */
 12→export function printSummary(
 13→  scenarioName: string,
 14→  metrics: OperationMetrics[],
 15→  totalDurationMs: number,
 16→  clientCount: number
 17→): void {
 18→  const totalOps = metrics.reduce((sum, m) => sum + m.count, 0);
 19→  const totalErrors = metrics.reduce((sum, m) => sum + m.errors, 0);
 20→  const totalBytes = metrics.reduce((sum, m) => sum + (m.bytesTransferred ?? 0), 0);
 21→
 22→  console.log(`\n${'='.repeat(80)}`);
 23→  console.log(`LOAD TEST: ${scenarioName}`);
 24→  console.log(`${'='.repeat(80)}`);
 25→  console.log(`Clients:     ${clientCount}`);
 26→  console.log(`Duration:    ${(totalDurationMs / 1000).toFixed(1)}s`);
 27→  console.log(`Total ops:   ${totalOps} (${totalErrors} errors)`);
 28→  const durationSec = Math.max(totalDurationMs, 1) / 1000;
 29→  console.log(`Throughput:  ${(totalOps / durationSec).toFixed(2)} ops/sec`);
 30→  if (totalBytes > 0) {
 31→    console.log(`Data:        ${formatBytes(totalBytes)}`);
 32→  }
 33→  console.log(`${'─'.repeat(80)}`);
 34→
 35→  // Table header
 36→  console.log(
 37→    padRight('Operation', 22) +
 38→      padRight('Count', 8) +
 39→      padRight('Errors', 8) +
 40→      padRight('p50', 10) +
 41→      padRight('p95', 10) +
 42→      padRight('p99', 10) +
 43→      padRight('Max', 10)
 44→  );
 45→  console.log('─'.repeat(80));
 46→
 47→  for (const m of metrics) {
 48→    console.log(
 49→      padRight(m.operation, 22) +
 50→        padRight(String(m.count), 8) +
 51→        padRight(String(m.errors), 8) +
 52→        padRight(fmtMs(m.latency.p50), 10) +
 53→        padRight(fmtMs(m.latency.p95), 10) +
 54→        padRight(fmtMs(m.latency.p99), 10) +
 55→        padRight(fmtMs(m.latency.max), 10)
 56→    );
 57→  }
 58→
 59→  console.log(`${'='.repeat(80)}\n`);
 60→}
 61→
 62→/**
 63→ * Export metrics as JSON (for CI artifact upload).
 64→ */
 65→export function toJsonReport(
 66→  scenarioName: string,
 67→  metrics: OperationMetrics[],
 68→  totalDurationMs: number,
 69→  clientCount: number
 70→): string {
 71→  return JSON.stringify(
 72→    {
 73→      scenario: scenarioName,
 74→      clientCount,
 75→      totalDurationMs,
 76→      totalOps: metrics.reduce((sum, m) => sum + m.count, 0),
 77→      totalErrors: metrics.reduce((sum, m) => sum + m.errors, 0),
 78→      operations: metrics,
 79→      timestamp: new Date().toISOString(),
 80→    },
 81→    null,
 82→    2
 83→  );
 84→}
 85→
 86→function padRight(str: string, len: number): string {
 87→  return str.padEnd(len);
 88→}
 89→
 90→function fmtMs(ms: number): string {
 91→  if (ms < 1000) return `${Math.round(ms)}ms`;
 92→  return `${(ms / 1000).toFixed(1)}s`;
 93→}
 94→
 95→function formatBytes(bytes: number): string {
 96→  if (bytes < 1024) return `${bytes}B`;
 97→  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
 98→  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
 99→}
